    fn set_mask8x16(self, a: &mut mask8x16<Self>, index: usize, value: bool) -> () {
        assert!(
            index < 16usize,
            "mask lane index {index} is out of bounds for {} lanes",
            16usize
        );
        let bit = 1u64 << index;
        let bits = u64::from((a).val);
        let bits = if value { bits | bit } else { bits & !bit };
        *a = mask8x16 {
            val: (bits) as _,
            simd: self,
        };
    }
